import type { QueueJob } from '@pikku/core/queue'
import type { Safe } from '@pikku/core/classification'

interface QueueHandler<I, O> {
    input: I;
    output: O;
}

export type QueueMap = {
  readonly 'pikku-virtual-user-runs': QueueHandler<ExecuteVirtualUserRunInput, ExecuteVirtualUserRunOutput>,
  readonly 'stripe-webhook-event': QueueHandler<ApplyStripeEventInput, ApplyStripeEventOutput>,
  readonly 'send-order-confirmation': QueueHandler<SendOrderConfirmationInput, null>,
  readonly 'audit-event': QueueHandler<WriteAuditEventInput, null>,
  readonly 'process-export': QueueHandler<ProcessExportInput, null>,
  readonly 'wf-orchestrator-checkout-workflow': QueueHandler<null, null>,
  readonly 'wf-orchestrator-refund-workflow': QueueHandler<null, null>,
};


type QueueAdd = <Name extends keyof QueueMap>(
  name: Name,
  data: Safe<QueueMap[Name]['input']>,
  options?: {
    priority?: number
    delay?: number
    attempts?: number
    removeOnComplete?: number
    removeOnFail?: number
    jobId?: string
  }
) => Promise<string>

type QueueGetJob = <Name extends keyof QueueMap>(
  name: Name,
  jobId: string
) => Promise<QueueJob<QueueMap[Name]['input'], QueueMap[Name]['output']> | null>

export type TypedPikkuQueue = {
  add: QueueAdd;
  getJob: QueueGetJob;
}
  